def fill_existing_orders(apps, schema_editor):
    """Orders placed before this change: items_total = old total, and a 'new' event for the timeline."""
    Order = apps.get_model("orders", "Order")
    OrderEvent = apps.get_model("orders", "OrderEvent")
    for order in Order.objects.all():
        order.items_total = order.total
        order.save(update_fields=["items_total"])
        event = OrderEvent.objects.create(order=order, status="new", by=order.user, note="Order placed")
        OrderEvent.objects.filter(pk=event.pk).update(created_at=order.created_at)
        if order.status != "new":
            OrderEvent.objects.create(order=order, status=order.status, note="(before history was recorded)")



